- [ ] **Step 1: Write the failing tests** — append to `config.test.ts`. A fake `secrets` executable is written first on `PATH`; because `resolvePrivateKeySecret` reads `process.env` (like `executePrivateKeyCommand`, see the existing leak test at `:890-939`), the tests mutate `process.env.PATH` and restore it in `finally`.

```ts
import fs from "node:fs";
import os from "node:os";
// (add to the existing imports at the top of the file)

/** A fake `secrets` first on PATH. `status` is what `get <NAME> --no-request` prints on stdout;
 * `value` is what `get <NAME> --value` prints; `statusExit`/`valueExit` and `stderr` shape the
 * failure cases. Every invocation appends one line to `<dir>/calls`:
 * `<argv>\t<readlink /proc/self/fd/0>\t<SECRETSD_SESSION_TOKEN_FILE or "unset">`. */
function withFakeSecrets(
  fake: { status?: string; statusExit?: number; value?: string; valueExit?: number; stderr?: string },
  run: (calls: () => string[]) => void
): void {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "legion-fake-secrets-"));
  const callsFile = path.join(dir, "calls");
  const script = [
    "#!/bin/sh",
    `printf '%s\\t%s\\t%s\\n' "$*" "$(readlink /proc/self/fd/0)" "\${SECRETSD_SESSION_TOKEN_FILE:-unset}" >> "${callsFile}"`,
    `if [ -n "${fake.stderr ?? ""}" ]; then printf '%s\\n' "${fake.stderr ?? ""}" >&2; fi`,
    'case "$*" in',
    `  *--no-request*) printf '%s\\n' '${fake.status ?? ""}'; exit ${fake.statusExit ?? 0} ;;`,
    `  *--value*) printf '%s\\n' '${fake.value ?? ""}'; exit ${fake.valueExit ?? 0} ;;`,
    "esac",
    "exit 2",
  ].join("\n");
  fs.writeFileSync(path.join(dir, "secrets"), script, { mode: 0o755 });
  const savedPath = process.env.PATH;
  process.env.PATH = `${dir}${path.delimiter}${savedPath}`;
  try {
    run(() => (fs.existsSync(callsFile) ? fs.readFileSync(callsFile, "utf8").trim().split("\n") : []));
  } finally {
    process.env.PATH = savedPath;
  }
}

const FAKE_PEM = "-----BEGIN RSA PRIVATE KEY-----\nMIIBOgIBAAJBAK\n-----END RSA PRIVATE KEY-----\n";
const FAKE_PEM_B64 = Buffer.from(FAKE_PEM).toString("base64");

function secretYaml(name = "GH_AGENT_APP_PRIVATE_KEY_B64"): string {
  return [
    ...baseYaml,
    "github_apps:",
    "  implement:",
    '    app_id: "1"',
    `    private_key_secret: ${name}`,
  ].join("\n");
}

it("refuses an agent-tier private_key_secret naming the key, without ever fetching the value", () => {
  withFakeSecrets({ status: '{"key":"GH_AGENT_APP_PRIVATE_KEY_B64","tier":"agent"}' }, (calls) => {
    expect(() => loadConfigFromFile(secretYaml(), "/tmp/legion-config")).toThrow(
      "App private key GH_AGENT_APP_PRIVATE_KEY_B64 is readable by agent-tier callers; move it to a daemon-only store"
    );
    expect(calls().map((line) => line.split("\t")[0])).toEqual([
      "get GH_AGENT_APP_PRIVATE_KEY_B64 --no-request",
    ]);
  });
});

it("resolves a human-tier private_key_secret to the decoded PEM, status before value, on the daemon's own stdin, without a session token", () => {
  const savedToken = process.env.SECRETSD_SESSION_TOKEN_FILE;
  process.env.SECRETSD_SESSION_TOKEN_FILE = "/leaked/agent-session-token";
  try {
    withFakeSecrets(
      { status: '{"key":"GH_AGENT_APP_PRIVATE_KEY_B64","tier":"human","grant":false}', value: FAKE_PEM_B64 },
      (calls) => {
        const file = loadConfigFromFile(secretYaml(), "/tmp/legion-config");
        const { config } = resolveDaemonConfig({ configFile: file });
        expect(config.githubApps.implement?.privateKey).toBe(FAKE_PEM.trim());
        const rows = calls().map((line) => line.split("\t"));
        expect(rows.map((row) => row[0])).toEqual([
          "get GH_AGENT_APP_PRIVATE_KEY_B64 --no-request",
          "get GH_AGENT_APP_PRIVATE_KEY_B64 --value",
        ]);
        // secretsd finds a caller's terminal through isatty(stdin) + /proc/self/fd/0, so both
        // children must run on the daemon's own fd 0, not a pipe.
        const ownStdin = fs.readlinkSync("/proc/self/fd/0");
        for (const row of rows) expect(row[1]).toBe(ownStdin);
        // The daemon's grant is the launcher pane's (tty scope), never an agent session's.
        for (const row of rows) expect(row[2]).toBe("unset");
      }
    );
  } finally {
    if (savedToken === undefined) delete process.env.SECRETSD_SESSION_TOKEN_FILE;
    else process.env.SECRETSD_SESSION_TOKEN_FILE = savedToken;
  }
});

